    """Complete missing reflected copies across adjacent equal-sized panels."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Full nonzero uniform lines form the panel separators.
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != 0]

    def spans(n, separators):
        result, start = [], 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rows = spans(h, sep_rows)
    cols = spans(w, sep_cols)

    # Across each adjacent pair of column panels, an occupied panel is
    # reflected into its empty mate. Existing two-sided pairs are preserved.
    for r0, r1 in rows:
        for (c0, c1), (d0, d1) in zip(cols, cols[1:]):
            if r1 - r0 != d1 - d0 or c1 - c0 != d1 - d0:
                continue
            left = any(out[r][c] != 0 for r in range(r0, r1)
                       for c in range(c0, c1))
            right = any(out[r][c] != 0 for r in range(r0, r1)
                        for c in range(d0, d1))
            if left and not right:
                for i in range(r1 - r0):
                    for j in range(d1 - d0):
                        out[r0 + i][d1 - 1 - j] = out[r0 + i][c0 + j]
            elif right and not left:
                for i in range(r1 - r0):
                    for j in range(c1 - c0):
                        out[r0 + i][c0 + j] = out[r0 + i][d1 - 1 - j]

    # Likewise reflect across adjacent row panels.
    for c0, c1 in cols:
        for (r0, r1), (s0, s1) in zip(rows, rows[1:]):
            if r1 - r0 != s1 - s0 or c1 - c0 != r1 - r0:
                continue
            top = any(out[r][c] != 0 for r in range(r0, r1)
                      for c in range(c0, c1))
            bottom = any(out[r][c] != 0 for r in range(s0, s1)
                         for c in range(c0, c1))
            if top and not bottom:
                for i in range(s1 - s0):
                    for j in range(c1 - c0):
                        out[s1 - 1 - i][c0 + j] = out[r0 + i][c0 + j]
            elif bottom and not top:
                for i in range(r1 - r0):
                    for j in range(c1 - c0):
                        out[r0 + i][c0 + j] = out[s1 - 1 - i][c0 + j]

    return out
